{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成订单销售额城市排名Top2",
      "business_question": "按城市比较已完成订单的销售额总和，并按销售额降序排名取前两名。约束：只看已完成订单；指标为销售额总和；限制为降序取前两名。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心业务问题（各城市已完成订单销售额对比及Top2决策支持）。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0003",
                "alias": "total_sales_amount"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "top_n",
          "params": {
            "field": "total_sales_amount",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
